/* Administrative actions always use a separately authenticated server session. */
(function () {
  'use strict';
  const API = window.LumoAPI, $ = s => document.querySelector(s);
  API.enableReadBatching?.();
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const tokenKey = 'lumo-admin-session-v1';
  let token = sessionStorage.getItem(tokenKey) || '', tab = 'overview', rows = [], lastTrace = '', busy = false, epoch = 0;
  const menus = [['overview','工作台'],['payments','支付确认'],['fulfillment','仓库发货'],['aftersales','售后处理'],['refunds','退款确认'],['invoices','发票管理'],['interactions','评价与问答'],['tickets','客服工单'],['reconciliation','对账记录'],['inventory','库存管理'],['categories','分类导航'],['content','内容管理'],['analytics','行为记录']];
  const specs = { payments:['payment','list'],fulfillment:['fulfillment','list'],aftersales:['aftersale','list'],refunds:['refund','list'],invoices:['invoice','list'],interactions:['interaction','list'],tickets:['helpdesk','list'],reconciliation:['reconciliation','list'],analytics:['analytics','list'] };
  const statusNames = {PENDING:'待确认',SUCCEEDED:'已成功',READY:'待发货',DISPATCHED:'已发货',REQUESTED:'待处理',APPROVED:'已批准',RETURNING:'退货中',INSPECTED:'已验收',REFUNDING:'退款中',REFUNDED:'已退款',EXCHANGED:'已换货',ISSUED:'已开票',OPEN:'待回复',REPLIED:'已回复',CLOSED:'已关闭',MATCHED:'一致',DIFFERENCES:'有差异',PUBLISHED:'已公开',REJECTED:'已驳回',CANCELLED:'已取消'};
  const currency = n => '¥' + (Number(n || 0) / 100).toLocaleString('zh-CN',{minimumFractionDigits:2});
  const idKey = () => 'admin-' + (crypto.randomUUID ? crypto.randomUUID() : Date.now() + '-' + Math.random().toString(16).slice(2));
  const message = text => { const el=$('#admin-toast');el.textContent=text;el.style.display='block';setTimeout(()=>{el.style.display='none';},3500); };
  async function call(service,action,command={}) { try{const result=await API.call(service,action,command,{token,auth:true});lastTrace=API.requests()[0]?.traceId||'';return result;}catch(error){if(error.status===401){token='';sessionStorage.removeItem(tokenKey);epoch++;login();}throw error;} }
  window.LumoCategoryEditor?.configure({isAdmin:()=>!!token,scope:()=>API.getBase()+'|'+token,call,draw:()=>{if(tab==='categories'&&token)$('#admin-main').innerHTML=window.LumoCategoryEditor.render();},notify:message});
  function errorHTML(error){ return `<div class="admin-error">${esc(error.message || '请求失败')}${error.traceID || error.traceId ? `<div class="admin-trace">Trace ID: ${esc(error.traceID || error.traceId)}</div>`:''}</div>`; }
  function nav(){ $('#admin-nav').innerHTML=token?menus.map(([key,title])=>`<button class="admin-nav-btn ${tab===key?'active':''}" data-tab="${key}">${title}</button>`).join('')+'<a class="admin-nav-btn" href="index.html#/editor">商品与页面编辑 ↗</a><button class="admin-nav-btn" data-action="logout">退出管理账号</button>':''; }
  function login(){window.LumoCategoryEditor?.reset();nav();$('#admin-main').innerHTML=`<div class="admin-login"><h1>登录商城管理</h1><p class="admin-note">使用管理员账号处理支付、履约和售后。管理会话与商城顾客会话分别保存。</p><form id="admin-login"><label class="field">账号<input name="username" autocomplete="username" required></label><label class="field">密码<input type="password" name="password" autocomplete="current-password" required></label><button class="primary" type="submit">登录</button></form><div id="admin-error"></div></div>`; }
  function title(text,extra=''){ return `<div class="admin-title"><h1>${esc(text)}</h1>${extra}<button class="outline" data-action="reload">刷新</button></div>`; }
  const button=(action,id,label)=>`<button data-operation="${action}" data-id="${esc(id)}">${label}</button>`;
  function rowActions(row){const id=row.id;switch(tab){
    case 'payments':return row.status==='PENDING'?button('payment.confirm_demo',id,'确认演示收款'):'';
    case 'fulfillment':return (row.status==='READY'?button('fulfillment.dispatch',id,'确认出库')+button('fulfillment.cancel',id,'拦截取消'):'')+(row.status==='DISPATCHED'?button('logistics.deliver',id,'确认演示签收'):'');
    case 'aftersales':return (row.status==='REQUESTED'?button('aftersale.approve',id,'批准')+button('aftersale.reject',id,'驳回'):'')+(row.status==='RETURNING'?button('aftersale.inspect',id,'验收退货'):'')+((row.type==='refund'&&row.status==='APPROVED')||(row.type==='return'&&row.status==='INSPECTED')?button('aftersale.refund',id,'发起退款'):'')+(row.type==='exchange'&&row.status==='INSPECTED'?button('aftersale.exchange',id,'创建换货履约'):'');
    case 'refunds':return ['PENDING','PROCESSING'].includes(row.status)?button('refund.confirm_demo',id,'确认演示退款'):'';
    case 'invoices':return (row.status==='REQUESTED'?button('invoice.issue_demo',id,'演示开票'):'')+button('invoice.adjust_demo',id,'处理红冲')+button('invoice.reversals',id,'查看红冲记录');
    case 'interactions':return button('interaction.moderate',id,'审核')+(row.kind==='question'?button('interaction.answer',id,'回复问题'):'');
    case 'tickets':return button('helpdesk.get',id,'查看会话')+(row.status!=='CLOSED'?button('helpdesk.reply',id,'客服回复')+button('helpdesk.close',id,'关闭工单'):'');
    default:return '';
  }}
  function table(){ if(!rows.length)return '<div class="admin-empty">暂无记录</div>';return `<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>业务对象</th><th>内容 / 金额</th><th>状态</th><th>操作</th></tr></thead><tbody>${rows.map(row=>`<tr><td><strong>${esc(row.title || row.name || row.kind || row.type || '业务记录')}</strong><small>${esc(row.id)}</small><small>${row.order_id?'订单 '+esc(row.order_id):esc(row.user_id || '')}</small></td><td>${esc(row.body || row.reason || row.tracking_id || row.number || '')}${row.amount_cents!=null?currency(row.amount_cents):''}${row.details?`<small>${esc(JSON.stringify(row.details))}</small>`:''}${row.answer?`<small>${esc(row.answer)}</small>`:''}</td><td><span class="admin-state">${esc(statusNames[row.status]||row.status)}</span></td><td><div class="admin-actions">${rowActions(row)}</div></td></tr>`).join('')}</tbody></table></div>`; }
  function field(label,name,type='text',value='',extra=''){return `<label class="field ${extra}">${label}<input name="${name}" type="${type}" value="${esc(value)}" required></label>`;}
  function forms(){if(tab==='inventory')return `<section class="admin-section"><h2>查询与调整库存</h2><p class="admin-note">设置在库总量；库存服务校验已预占和已分配数量，禁止设置为更低的库存。</p><form id="inventory-query" class="admin-form">${field('SKU 编号','sku_id')}<div><button class="outline">查询库存</button></div></form><form id="inventory-adjust" class="admin-form" style="margin-top:24px">${field('SKU 编号','sku_id')}${field('在库总量（非负整数）','on_hand','number')}${field('调整原因','reason')}<div><button class="primary">提交调整</button></div></form><h2 style="margin-top:32px">仓库退货入库</h2><p class="admin-note">售后退货请优先在售后处理页验收。此处登记独立的仓库收货凭证，同一凭证重复提交不会重复入库。</p><form id="return-inspect" class="admin-form">${field('唯一验收凭证号','inspection_id')}${field('SKU 编号','sku_id')}${field('实收数量','quantity','number')}<label class="field">品质<select name="condition"><option value="sellable">可售</option><option value="damaged">破损</option><option value="unsellable">不可售</option></select></label><button class="primary">登记入库</button></form><div id="admin-result"></div></section>`;
    return `<section class="admin-section"><h2>商城内容</h2><p class="admin-note">发布帮助、公告及页面配置。商品与视觉布局可进入“商品与页面编辑”。</p><form id="content-save" class="admin-form">${field('内容编号','id')}${field('类型','kind','text','notice')}${field('标题','title','text','','wide')}<label class="field wide">正文<textarea name="body" required></textarea></label><button class="primary">发布内容</button></form><div id="admin-result"></div></section>`;
  }
  async function load(){ const revision=++epoch;nav();if(!token){login();return;}const name=menus.find(x=>x[0]===tab)?.[1]||'';$('#admin-main').innerHTML=title(name)+'<div class="admin-empty">正在读取…</div>';try{
      if(tab==='categories'){await window.LumoCategoryEditor.refresh();if(revision!==epoch)return;$('#admin-main').innerHTML=window.LumoCategoryEditor.render();return;}
      if(tab==='overview'){const all=await Promise.all([call('order','list'),call('aftersale','list'),call('helpdesk','list')]);if(revision!==epoch)return;$('#admin-main').innerHTML=title(name)+`<div class="admin-cards">${[['订单',all[0].items?.length||0],['待处理售后',(all[1].items||[]).filter(x=>x.status==='REQUESTED').length],['未关闭工单',(all[2].items||[]).filter(x=>x.status!=='CLOSED').length]].map(([name,n])=>`<div class="admin-card"><span>${name}</span><strong>${n}</strong><span>服务端实时记录</span></div>`).join('')}</div><section class="admin-section"><h2>交易处理</h2><p class="admin-note">顾客提交订单并创建支付单后，在“支付确认”中确认演示收款。订单资源确认完成后会进入仓库待发货；确认出库和演示签收后，顾客可确认收货、评价或申请售后。</p><p class="admin-note">支付、退款、物流和发票使用演示适配器；每一步均调用后端并保留状态记录。</p><a class="outline" href="index.html">打开商城</a></section>`;return;}
      if(tab==='inventory'||tab==='content'){if(revision===epoch)$('#admin-main').innerHTML=title(name)+forms();return;}
      if(tab==='interactions'){const [reviews,questions]=await Promise.all([call('interaction','list',{data:{kind:'review',include_pending:true}}),call('interaction','list',{data:{kind:'question',include_pending:true}})]);rows=[...(reviews.items||[]),...(questions.items||[])];}
      else{const [s,a]=specs[tab];const result=await call(s,a);rows=result.items||[];}
      if(revision!==epoch)return;$('#admin-main').innerHTML=title(name,tab==='reconciliation'?'<button class="primary" data-operation="reconciliation.run">执行内部对账</button>':'')+(tab==='payments'||tab==='refunds'?'<p class="admin-note">仅确认演示渠道回执。确认后请刷新查看下游订单或售后状态。</p>':'')+table()+`<div class="admin-trace">最近调用链路：${esc(lastTrace)}</div><section id="operation-result"></section>`;
    }catch(error){if(revision!==epoch)return;$('#admin-main').innerHTML=title(name)+errorHTML(error);}
  }
  function showResult(result){const target=$('#operation-result')||$('#admin-result');if(target)target.innerHTML=`<section class="admin-section"><h2>处理结果</h2><pre>${esc(JSON.stringify(result,null,2))}</pre><div class="admin-trace">链路编号：${esc(lastTrace)}</div></section>`;}
  document.addEventListener('click',async event=>{const target=event.target.closest('[data-tab],[data-action],[data-operation]');if(!target||busy)return;if(target.dataset.tab){tab=target.dataset.tab;load();return;}if(target.dataset.action==='reload'){load();return;}if(target.dataset.action==='logout'){try{await call('iam','logout');token='';sessionStorage.removeItem(tokenKey);login();}catch(error){message(error.message);}return;}
    if(!target.dataset.operation)return;const [service,action]=target.dataset.operation.split('.');const command={id:target.dataset.id||'',data:{},idempotency_key:idKey()};
    if(action==='inspect'){const condition=prompt('退货品质：sellable / damaged / unsellable','sellable');if(condition===null)return;if(!['sellable','damaged','unsellable'].includes(condition)){message('请选择有效品质');return;}command.data.condition=condition;}
    if(service==='interaction'&&action==='moderate'){const approved=confirm('确定公开此内容？点击取消可选择驳回。');if(!approved&&!confirm('是否驳回此内容？'))return;command.data.approved=approved;}
    if(action==='answer'||action==='reply'){const body=prompt('输入回复内容');if(!body?.trim())return;command.data[action==='answer'?'answer':'body']=body.trim();}
    busy=true;target.disabled=true;try{const result=await call(service,action,command);if(action==='get'||action==='reversals')showResult(result);else{message('后端已受理');await load();showResult(result);}}catch(error){const el=$('#operation-result');if(el)el.innerHTML=errorHTML(error);else message(error.message);}finally{busy=false;target.disabled=false;}
  });
  document.addEventListener('submit',async event=>{const form=event.target;if(!['admin-login','inventory-query','inventory-adjust','return-inspect','content-save'].includes(form.id))return;event.preventDefault();if(busy)return;busy=true;const button=form.querySelector('button');button.disabled=true;const data=Object.fromEntries(new FormData(form));try{
      if(form.id==='admin-login'){const session=await API.call('iam','login',{data},{auth:false,token:''});if(session.role!=='admin'){await API.call('iam','logout',{}, {token:session.token});throw Error('此账号没有管理员权限');}token=session.token;sessionStorage.setItem(tokenKey,token);form.reset();await load();}
      if(form.id==='inventory-query')showResult(await call('inventory','get',{id:data.sku_id}));
      if(form.id==='inventory-adjust')showResult(await call('inventory','adjust',{id:data.sku_id,idempotency_key:idKey(),data:{on_hand:Number(data.on_hand),reason:data.reason}}));
      if(form.id==='return-inspect')showResult(await call('fulfillment','inspect_return',{id:data.inspection_id,data:{sku_id:data.sku_id,quantity:Number(data.quantity),condition:data.condition}}));
      if(form.id==='content-save'){const id=data.id;delete data.id;data.active=true;showResult(await call('content','upsert',{id,data}));}
    }catch(error){const el=$('#admin-error')||$('#admin-result');if(el)el.innerHTML=errorHTML(error);else message(error.message);}finally{busy=false;button.disabled=false;}
  });
  (async()=>{if(token){try{const principal=await call('iam','current');if(principal.role!=='admin')throw Error('管理员身份无效');}catch(_){token='';sessionStorage.removeItem(tokenKey);}}await load();})();
})();
